import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Use hipcc for ROCm builds
os.environ.setdefault("CXX", "hipcc")

# Fused kernel: for each row, compute sum over pooled outputs and apply scale.
# Matches: x -> MaxPool1d(kernel_size, stride=kernel_size) on a length-N vector, then sum, then scale.
# For kernel_size=2 (the benchmark), this is: sum_i max(x[2i], x[2i+1]).

fused_cpp_source = r"""
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA/HIP tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_FLOAT
#define CHECK_FLOAT(x) TORCH_CHECK(x.scalar_type() == at::kFloat, #x " must be float32")
#endif

static inline __device__ float warp_reduce_sum(float v) {
    // AMD wavefront is 64 lanes.
    for (int offset = 32; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset);
    }
    return v;
}

__global__ void maxpool_sum_scale_k2_kernel(const float* __restrict__ x,
                                            float* __restrict__ out,
                                            int64_t N,
                                            float scale) {
    // One block per row
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;

    float acc = 0.0f;

    // kernel_size=2, stride=2. Assume floor(N/2) windows.
    int64_t num_pairs = N >> 1; // N/2

    // Process float2 for coalesced loads when possible
    const float2* row2 = reinterpret_cast<const float2*>(row_ptr);
    int64_t n2 = num_pairs; // number of float2 elements

    int tid = (int)threadIdx.x;
    int64_t idx = tid;
    int64_t stride = (int64_t)blockDim.x;

    while (idx < n2) {
        float2 v = row2[idx];
        acc += fmaxf(v.x, v.y);
        idx += stride;
    }

    // Reduce within block
    // First reduce within each wavefront
    acc = warp_reduce_sum(acc);

    __shared__ float smem[8]; // enough for up to 8 wavefronts (blockDim<=512)
    int lane = tid & 63;
    int wave = tid >> 6;
    if (lane == 0) smem[wave] = acc;
    __syncthreads();

    // First wave reduces wave sums
    float block_sum = 0.0f;
    if (wave == 0) {
        block_sum = (tid < (blockDim.x + 63) / 64) ? smem[lane] : 0.0f;
        block_sum = warp_reduce_sum(block_sum);
        if (tid == 0) out[row] = block_sum * scale;
    }
}

__global__ void maxpool_sum_scale_generic_kernel(const float* __restrict__ x,
                                                 float* __restrict__ out,
                                                 int64_t N,
                                                 int k,
                                                 float scale) {
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;

    int64_t out_len = N / k; // stride=k, no padding

    float acc = 0.0f;
    int tid = (int)threadIdx.x;
    int64_t idx = tid;
    int64_t stride = (int64_t)blockDim.x;

    while (idx < out_len) {
        int64_t base = idx * k;
        float m = row_ptr[base];
        #pragma unroll
        for (int t = 1; t < 16; t++) {
            if (t < k) m = fmaxf(m, row_ptr[base + t]);
        }
        acc += m;
        idx += stride;
    }

    acc = warp_reduce_sum(acc);

    __shared__ float smem[8];
    int lane = tid & 63;
    int wave = tid >> 6;
    if (lane == 0) smem[wave] = acc;
    __syncthreads();

    float block_sum = 0.0f;
    if (wave == 0) {
        block_sum = (tid < (blockDim.x + 63) / 64) ? smem[lane] : 0.0f;
        block_sum = warp_reduce_sum(block_sum);
        if (tid == 0) out[row] = block_sum * scale;
    }
}

torch::Tensor maxpool_sum_scale_hip(torch::Tensor x, double scale_factor, int64_t kernel_size) {
    CHECK_CUDA(x);
    CHECK_FLOAT(x);
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
    TORCH_CHECK(kernel_size > 0, "kernel_size must be > 0");

    auto x_contig = x.contiguous();
    int64_t B = x_contig.size(0);
    int64_t N = x_contig.size(1);

    auto out = torch::empty({B}, x_contig.options());

    const int threads = 256; // 4 wavefronts
    dim3 block(threads);
    dim3 grid((unsigned)B);

    hipStream_t stream = at::hip::getDefaultHIPStream();
    float scale = (float)scale_factor;

    if (kernel_size == 2 && (N % 2 == 0)) {
        hipLaunchKernelGGL(maxpool_sum_scale_k2_kernel, grid, block, 0, stream,
                           (const float*)x_contig.data_ptr<float>(),
                           (float*)out.data_ptr<float>(),
                           N,
                           scale);
    } else {
        TORCH_CHECK(kernel_size <= 16, "generic kernel supports kernel_size<=16");
        hipLaunchKernelGGL(maxpool_sum_scale_generic_kernel, grid, block, 0, stream,
                           (const float*)x_contig.data_ptr<float>(),
                           (float*)out.data_ptr<float>(),
                           N,
                           (int)kernel_size,
                           scale);
    }

    // Best-effort error check
    auto err = hipGetLastError();
    TORCH_CHECK(err == hipSuccess, "HIP kernel launch failed: ", hipGetErrorString(err));
    return out;
}
"""

fused_mod = load_inline(
    name="fused_maxpool_sum_scale_ext",
    cpp_sources=fused_cpp_source,
    functions=["maxpool_sum_scale_hip"],
    extra_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized model: keep GEMM via rocBLAS, fuse maxpool+sum+scale into one HIP kernel."""

    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super().__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.kernel_size = int(kernel_size)
        self.scale_factor = float(scale_factor)
        self.fused = fused_mod

    def forward(self, x):
        x = self.matmul(x)
        # Fused: MaxPool1d(stride=kernel_size) + sum(dim=1) + scale
        return self.fused.maxpool_sum_scale_hip(x, self.scale_factor, self.kernel_size)


# KernelBench harness functions
batch_size = 128
in_features = 32768
out_features = 32768
kernel_size = 2
scale_factor = 0.5

def get_inputs():
    return [torch.rand(batch_size, in_features)]

def get_init_inputs():
    return [in_features, out_features, kernel_size, scale_factor]

