import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation
os.environ.setdefault("CXX", "hipcc")

# Fused: GELU (exact, erf) + Softmax(dim=1) in-place on [B, N] FP32 tensor.
# We keep nn.Linear unchanged (rocBLAS GEMM dominates), but remove intermediate GELU/Softmax tensors
# and fuse them into a single kernel to cut memory traffic and launch overhead.

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

#ifndef __HIP_PLATFORM_AMD__
#define __HIP_PLATFORM_AMD__ 1
#endif

static inline __device__ float gelu_erf(float x) {
    // Exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
    const float inv_sqrt2 = 0.70710678118654752440f;
    return 0.5f * x * (1.0f + erff(x * inv_sqrt2));
}

template<int BLOCK>
__global__ void gelu_softmax_inplace_kernel(float* __restrict__ x, int rows, int cols) {
    // One block per row.
    int row = (int)blockIdx.x;
    if (row >= rows) return;

    constexpr int WARP = 64; // AMD wavefront
    constexpr int WARPS = BLOCK / WARP;

    // Shared storage for warp partials
    __shared__ float s_max[WARPS];
    __shared__ float s_sum[WARPS];

    float* row_ptr = x + (size_t)row * (size_t)cols;

    // Pass 1: compute max over GELU(x)
    float local_max = -INFINITY;
    for (int c = (int)threadIdx.x; c < cols; c += BLOCK) {
        float v = gelu_erf(row_ptr[c]);
        local_max = fmaxf(local_max, v);
    }

    // Warp reduce max
    float v = local_max;
    #pragma unroll
    for (int offset = WARP / 2; offset > 0; offset >>= 1) {
        v = fmaxf(v, __shfl_down(v, offset, WARP));
    }
    int lane = (int)(threadIdx.x & (WARP - 1));
    int warp = (int)(threadIdx.x / WARP);
    if (lane == 0) s_max[warp] = v;
    __syncthreads();

    float row_max;
    if (warp == 0) {
        float wm = (lane < WARPS) ? s_max[lane] : -INFINITY;
        #pragma unroll
        for (int offset = WARP / 2; offset > 0; offset >>= 1) {
            wm = fmaxf(wm, __shfl_down(wm, offset, WARP));
        }
        if (lane == 0) s_max[0] = wm;
    }
    __syncthreads();
    row_max = s_max[0];

    // Pass 2: compute exp(gelu(x)-max), store to x, and reduce sum
    float local_sum = 0.0f;
    for (int c = (int)threadIdx.x; c < cols; c += BLOCK) {
        float gv = gelu_erf(row_ptr[c]);
        float ev = expf(gv - row_max);
        row_ptr[c] = ev; // temporary
        local_sum += ev;
    }

    // Warp reduce sum
    float s = local_sum;
    #pragma unroll
    for (int offset = WARP / 2; offset > 0; offset >>= 1) {
        s += __shfl_down(s, offset, WARP);
    }
    if (lane == 0) s_sum[warp] = s;
    __syncthreads();

    float row_sum;
    if (warp == 0) {
        float ws = (lane < WARPS) ? s_sum[lane] : 0.0f;
        #pragma unroll
        for (int offset = WARP / 2; offset > 0; offset >>= 1) {
            ws += __shfl_down(ws, offset, WARP);
        }
        if (lane == 0) s_sum[0] = ws;
    }
    __syncthreads();
    row_sum = s_sum[0];

    // Pass 3: normalize
    float inv = 1.0f / row_sum;
    for (int c = (int)threadIdx.x; c < cols; c += BLOCK) {
        row_ptr[c] *= inv;
    }
}

torch::Tensor gelu_softmax_inplace_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int rows = (int)x.size(0);
    int cols = (int)x.size(1);

    const int BLOCK = 256;
    dim3 grid(rows);
    dim3 block(BLOCK);

    hipLaunchKernelGGL((gelu_softmax_inplace_kernel<BLOCK>), grid, block, 0, 0,
                      (float*)x.data_ptr<float>(), rows, cols);
    return x;
}
"""

# Build extension
fused = load_inline(
    name="fused_gelu_softmax_ext",
    cpp_sources=hip_src,
    functions=["gelu_softmax_inplace_hip"],
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized model: keep GEMM from nn.Linear, fuse GELU+Softmax into one HIP kernel (in-place)."""

    def __init__(self, in_features, out_features):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.fused = fused

    def forward(self, x):
        x = self.linear(x)
        # in-place fused GELU+Softmax
        return self.fused.gelu_softmax_inplace_hip(x)


# Keep KernelBench API
batch_size = 1024
in_features = 8192
out_features = 8192

def get_inputs():
    return [torch.rand(batch_size, in_features)]

def get_init_inputs():
    return [in_features, out_features]

