import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Compile HIP/ROCm extension (fused: maxpool over conv output, then tanh+scale+bias)
# This is mathematically exact for scaling_factor >= 0 because tanh is monotonic.
os.environ.setdefault("CXX", "hipcc")

_cuda_src = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Fused kernel: for each output element (n,c,oh,ow)
// 1) reduce over a 4x4 window in the input (conv output) with stride=4
// 2) apply tanh, scaling, and bias
//
// If scaling < 0, we reduce with min instead of max (monotonic decreasing).
__global__ void fused_pool_tanh_scale_bias_4x4_s4(
    const float* __restrict__ in,
    const float* __restrict__ bias_c,
    float* __restrict__ out,
    int N, int C, int H, int W,
    int Hout, int Wout,
    float scale)
{
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * Hout * Wout;
    if (idx >= total) return;

    int ow = idx % Wout;
    int t = idx / Wout;
    int oh = t % Hout;
    t /= Hout;
    int c = t % C;
    int n = t / C;

    // window start
    int ih0 = oh * 4;
    int iw0 = ow * 4;

    // Base offset for (n,c,ih0,iw0)
    const float* p0 = in + ((n * C + c) * H + ih0) * W + iw0;

    // Reduce over 4x4
    float acc;
    if (scale >= 0.0f) {
        acc = -INFINITY;
        #pragma unroll
        for (int r = 0; r < 4; r++) {
            const float* pr = p0 + r * W;
            // unrolled 4 cols
            float v0 = pr[0];
            float v1 = pr[1];
            float v2 = pr[2];
            float v3 = pr[3];
            acc = fmaxf(acc, v0);
            acc = fmaxf(acc, v1);
            acc = fmaxf(acc, v2);
            acc = fmaxf(acc, v3);
        }
    } else {
        acc = INFINITY;
        #pragma unroll
        for (int r = 0; r < 4; r++) {
            const float* pr = p0 + r * W;
            float v0 = pr[0];
            float v1 = pr[1];
            float v2 = pr[2];
            float v3 = pr[3];
            acc = fminf(acc, v0);
            acc = fminf(acc, v1);
            acc = fminf(acc, v2);
            acc = fminf(acc, v3);
        }
    }

    float b = bias_c[c];
    float y = tanhf(acc) * scale + b;
    out[idx] = y;
}

torch::Tensor fused_tanh_scale_bias_maxpool(torch::Tensor x, torch::Tensor bias, double scaling_factor) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/HIP tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");

    x = x.contiguous();
    bias = bias.contiguous();

    const int64_t N = x.size(0);
    const int64_t C = x.size(1);
    const int64_t H = x.size(2);
    const int64_t W = x.size(3);

    // Expect bias shape (C,1,1) or (C)
    TORCH_CHECK(bias.numel() == C, "bias must have numel == C");

    // Fixed pool kernel=4, stride=4
    const int k = 4;
    const int s = 4;
    TORCH_CHECK(H >= k && W >= k, "H/W too small for 4x4 pool");

    const int64_t Hout = (H - k) / s + 1;
    const int64_t Wout = (W - k) / s + 1;

    auto out = torch::empty({N, C, Hout, Wout}, x.options());

    int total = (int)(N * C * Hout * Wout);
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    float scale = (float)scaling_factor;

    // Use the current CUDA/HIP stream
    auto stream = at::cuda::getDefaultCUDAStream();
    hipStream_t hip_stream = (hipStream_t)stream.stream();

    fused_pool_tanh_scale_bias_4x4_s4<<<blocks, threads, 0, hip_stream>>>(
        (const float*)x.data_ptr<float>(),
        (const float*)bias.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)W,
        (int)Hout, (int)Wout,
        scale
    );

    return out;
}
'''

# Build extension once per process
_fused_ext = load_inline(
    name="fused_tanh_scale_bias_maxpool_ext",
    cpp_sources="",
    cuda_sources=_cuda_src,
    functions=["fused_tanh_scale_bias_maxpool"],
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized: conv2d + fused(maxpool -> tanh + scaling + bias)."""

    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = float(scaling_factor)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        # pool_kernel_size is expected to be 4 in this benchmark
        self.pool_kernel_size = pool_kernel_size

    def forward(self, x):
        x = self.conv(x)
        # Fused op assumes pool_kernel_size == 4
        if self.pool_kernel_size != 4:
            # Fallback to PyTorch path for unexpected configs
            x = torch.tanh(x)
            x = x * self.scaling_factor
            x = x + self.bias
            x = torch.nn.functional.max_pool2d(x, self.pool_kernel_size)
            return x
        return _fused_ext.fused_tanh_scale_bias_maxpool(x, self.bias, self.scaling_factor)


