    TORCH_CHECK(mean.is_cuda() && var.is_cuda(), "mish_bn_inference_hip: mean/var must be CUDA");
    TORCH_CHECK(mean.dtype() == torch::kFloat32 && var.dtype() == torch::kFloat32, "mish_bn_inference_hip: mean/var must be float32");

