import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ.setdefault("CXX", "hipcc")

# Improved fused kernel: keep values in registers (32 elems/thread for N=8192, block=256)
# so we only compute GELU+EXP once and only write final normalized output once.

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

static inline __device__ float gelu_erf(float x) {
    const float inv_sqrt2 = 0.70710678118654752440f;
    return 0.5f * x * (1.0f + erff(x * inv_sqrt2));
}

template<int BLOCK, int MAX_ELEMS>
__global__ void gelu_softmax_inplace_kernel(float* __restrict__ x, int rows, int cols) {
    int row = (int)blockIdx.x;
    if (row >= rows) return;

    constexpr int WARP = 64;
    constexpr int WARPS = BLOCK / WARP;
    __shared__ float s_max[WARPS];
    __shared__ float s_sum[WARPS];

    float* row_ptr = x + (size_t)row * (size_t)cols;

    // Load + GELU once, keep in registers.
    float vals[MAX_ELEMS];
    float local_max = -INFINITY;

    #pragma unroll
    for (int i = 0; i < MAX_ELEMS; ++i) {
        int c = (int)threadIdx.x + i * BLOCK;
        float v = -INFINITY;
        if (c < cols) {
            v = gelu_erf(row_ptr[c]);
            local_max = fmaxf(local_max, v);
        }
        vals[i] = v;
    }

    // Reduce max within block
    float v = local_max;
    #pragma unroll
    for (int offset = WARP / 2; offset > 0; offset >>= 1) {
        v = fmaxf(v, __shfl_down(v, offset, WARP));
    }
    int lane = (int)(threadIdx.x & (WARP - 1));
    int warp = (int)(threadIdx.x / WARP);
    if (lane == 0) s_max[warp] = v;
    __syncthreads();

    float row_max;
    if (warp == 0) {
        float wm = (lane < WARPS) ? s_max[lane] : -INFINITY;
        #pragma unroll
        for (int offset = WARP / 2; offset > 0; offset >>= 1) {
            wm = fmaxf(wm, __shfl_down(wm, offset, WARP));
        }
        if (lane == 0) s_max[0] = wm;
    }
    __syncthreads();
    row_max = s_max[0];

    // Compute exp(vals - max) and local sum; reuse vals[] to hold exp
    float local_sum = 0.0f;
    #pragma unroll
    for (int i = 0; i < MAX_ELEMS; ++i) {
        float gv = vals[i];
        float ev = 0.0f;
        if (gv != -INFINITY) {
            ev = expf(gv - row_max);
            local_sum += ev;
        }
        vals[i] = ev;
    }

    // Reduce sum within block
    float s = local_sum;
    #pragma unroll
    for (int offset = WARP / 2; offset > 0; offset >>= 1) {
        s += __shfl_down(s, offset, WARP);
    }
    if (lane == 0) s_sum[warp] = s;
    __syncthreads();

    float row_sum;
    if (warp == 0) {
        float ws = (lane < WARPS) ? s_sum[lane] : 0.0f;
        #pragma unroll
        for (int offset = WARP / 2; offset > 0; offset >>= 1) {
            ws += __shfl_down(ws, offset, WARP);
        }
        if (lane == 0) s_sum[0] = ws;
    }
    __syncthreads();
    row_sum = s_sum[0];

    float inv = 1.0f / row_sum;
    // Store normalized output
    #pragma unroll
    for (int i = 0; i < MAX_ELEMS; ++i) {
        int c = (int)threadIdx.x + i * BLOCK;
        if (c < cols) {
            row_ptr[c] = vals[i] * inv;
        }
    }
}

torch::Tensor gelu_softmax_inplace_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int rows = (int)x.size(0);
    int cols = (int)x.size(1);

    // Tuned for cols=8192, BLOCK=256 => 32 elems/thread.
    const int BLOCK = 256;
    const int MAX_ELEMS = 32;

    dim3 grid(rows);
    dim3 block(BLOCK);

    hipLaunchKernelGGL((gelu_softmax_inplace_kernel<BLOCK, MAX_ELEMS>), grid, block, 0, 0,
                      (float*)x.data_ptr<float>(), rows, cols);
    return x;
}
"""

fused = load_inline(
    name="fused_gelu_softmax_ext_v2",
    cpp_sources=hip_src,
    functions=["gelu_softmax_inplace_hip"],
    with_cuda=True,
    extra_cuda_cflags=["-O3", "-ffast-math"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
