# Keep Linear (GEMM) on rocBLAS; focus on minimizing post-op overhead.

fused_cpp_source = r"""
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA/HIP tensor")
#define CHECK_FLOAT(x) TORCH_CHECK(x.scalar_type() == at::kFloat, #x " must be float32")

static inline __device__ float wave_reduce_sum(float v) {
    // AMD wavefront = 64
    for (int offset = 32; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset);
    }
    return v;
}

template<int NUM_WAVES>
static inline __device__ float block_reduce_sum(float v) {
    v = wave_reduce_sum(v);
    __shared__ float smem[NUM_WAVES];
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int wave = tid >> 6;
    if (lane == 0) smem[wave] = v;
    __syncthreads();

    float sum = 0.0f;
    if (wave == 0) {
        sum = (lane < NUM_WAVES) ? smem[lane] : 0.0f;
        sum = wave_reduce_sum(sum);
    }
    return sum;
}

__global__ void maxpool_sum_scale_k2_kernel_f4(const float* __restrict__ x,
                                               float* __restrict__ out,
                                               int64_t N,
                                               float scale) {
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;

    // kernel_size=2, stride=2 => num_pairs = N/2
    // Process 2 pairs per iteration with float4.
    int64_t num_f4 = (N >> 2); // N/4 float4 values == (N/2 pairs)/2
    const float4* row4 = reinterpret_cast<const float4*>(row_ptr);

    float acc = 0.0f;
    int tid = (int)threadIdx.x;
    int64_t i = tid;
    int64_t stride = (int64_t)blockDim.x;

    // Each float4: (a0,a1,a2,a3) => pairs (a0,a1), (a2,a3)
    while (i < num_f4) {
        float4 v = row4[i];
        acc += fmaxf(v.x, v.y) + fmaxf(v.z, v.w);
        i += stride;
    }

    // Reduce in block
    float sum = block_reduce_sum<8>(acc); // assumes blockDim=512 => 8 waves
    if (threadIdx.x == 0) out[row] = sum * scale;
}

__global__ void maxpool_sum_scale_k2_kernel_f2(const float* __restrict__ x,
                                               float* __restrict__ out,
                                               int64_t N,
                                               float scale) {
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;

    int64_t num_pairs = N >> 1;
    const float2* row2 = reinterpret_cast<const float2*>(row_ptr);

    float acc = 0.0f;
    int tid = (int)threadIdx.x;
    int64_t i = tid;
    int64_t stride = (int64_t)blockDim.x;

    while (i < num_pairs) {
        float2 v = row2[i];
        acc += fmaxf(v.x, v.y);
        i += stride;
    }

    float sum = block_reduce_sum<4>(acc); // assumes blockDim=256 => 4 waves
    if (threadIdx.x == 0) out[row] = sum * scale;
}

__global__ void maxpool_sum_scale_generic_kernel(const float* __restrict__ x,
                                                 float* __restrict__ out,
                                                 int64_t N,
                                                 int k,
                                                 float scale) {
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;
    int64_t out_len = N / k;

    float acc = 0.0f;
    int tid = (int)threadIdx.x;
    int64_t i = tid;
    int64_t stride = (int64_t)blockDim.x;

    while (i < out_len) {
        int64_t base = i * k;
        float m = row_ptr[base];
        #pragma unroll
        for (int t = 1; t < 16; t++) {
            if (t < k) m = fmaxf(m, row_ptr[base + t]);
        }
        acc += m;
        i += stride;
    }

    float sum = block_reduce_sum<4>(acc);
    if (threadIdx.x == 0) out[row] = sum * scale;
}

torch::Tensor maxpool_sum_scale_hip(torch::Tensor x, double scale_factor, int64_t kernel_size) {
    CHECK_CUDA(x);
