import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ.setdefault("CXX", "hipcc")

# Strategy:
# - Keep Linear on rocBLAS (highly optimized)
# - Replace MaxPool1d+sum+scale with a custom HIP implementation.
# - For kernel_size=2 we use a 2-stage reduction to increase parallelism on MI300X:
#     stage1: per-(row,chunk) partial sum of max over pairs using many blocks
#     stage2: per-row reduction over chunk partials and scaling

fused_cpp_source = r"""
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA/HIP tensor")
#define CHECK_FLOAT(x) TORCH_CHECK(x.scalar_type() == at::kFloat, #x " must be float32")

static inline __device__ float wave_reduce_sum(float v) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        v += __shfl_down(v, offset);
    }
    return v;
}

template<int NUM_WAVES>
static inline __device__ float block_reduce_sum(float v) {
    v = wave_reduce_sum(v);
    __shared__ float smem[NUM_WAVES];
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int wave = tid >> 6;
    if (lane == 0) smem[wave] = v;
    __syncthreads();
    float sum = 0.0f;
    if (wave == 0) {
        sum = (lane < NUM_WAVES) ? smem[lane] : 0.0f;
        sum = wave_reduce_sum(sum);
    }
    return sum;
}

// Stage 1: compute partial sums for kernel_size=2 using float4 (two pairs per load).
// Grid: (B rows, CHUNKS)
// Each block processes a contiguous chunk of float4s.
// CHUNK_F4 * 4 floats per chunk.

template<int CHUNK_F4>
__global__ void k2_partial_sum_f4_kernel(const float* __restrict__ x,
                                        float* __restrict__ partial,
                                        int64_t N,
                                        int chunks) {
    int row = (int)blockIdx.x;
    int chunk = (int)blockIdx.y;

    const float4* row4 = reinterpret_cast<const float4*>(x + (int64_t)row * N);
    int64_t total_f4 = (N >> 2);
    int64_t start = (int64_t)chunk * CHUNK_F4;

    float acc = 0.0f;
    int tid = (int)threadIdx.x;

    // Bounds-safe in case N not exactly chunks*CHUNK_F4*4
    for (int64_t i = tid; i < CHUNK_F4; i += (int64_t)blockDim.x) {
        int64_t idx = start + i;
        if (idx < total_f4) {
            float4 v = row4[idx];
            acc += fmaxf(v.x, v.y) + fmaxf(v.z, v.w);
        }
    }

    float sum = block_reduce_sum<4>(acc); // blockDim=256 => 4 waves
    if (tid == 0) partial[(int64_t)row * chunks + chunk] = sum;
}

// Stage 2: reduce chunk partial sums per row and apply scaling.
__global__ void reduce_partials_scale_kernel(const float* __restrict__ partial,
                                            float* __restrict__ out,
                                            int chunks,
                                            float scale) {
    int row = (int)blockIdx.x;
    float acc = 0.0f;
    int tid = (int)threadIdx.x;

    const float* rowp = partial + (int64_t)row * chunks;
    for (int i = tid; i < chunks; i += (int)blockDim.x) {
        acc += rowp[i];
    }

    float sum = block_reduce_sum<4>(acc);
    if (tid == 0) out[row] = sum * scale;
}

// Fallback: single-block per row for generic kernel_size<=16
__global__ void maxpool_sum_scale_generic_kernel(const float* __restrict__ x,
                                                 float* __restrict__ out,
                                                 int64_t N,
                                                 int k,
                                                 float scale) {
    int row = (int)blockIdx.x;
    const float* row_ptr = x + (int64_t)row * N;
    int64_t out_len = N / k;

    float acc = 0.0f;
    int tid = (int)threadIdx.x;
    for (int64_t i = tid; i < out_len; i += (int64_t)blockDim.x) {
        int64_t base = i * k;
        float m = row_ptr[base];
        #pragma unroll
        for (int t = 1; t < 16; t++) {
            if (t < k) m = fmaxf(m, row_ptr[base + t]);
        }
        acc += m;
    }

    float sum = block_reduce_sum<4>(acc);
    if (tid == 0) out[row] = sum * scale;
}

torch::Tensor maxpool_sum_scale_hip(torch::Tensor x, double scale_factor, int64_t kernel_size) {
    CHECK_CUDA(x);
    CHECK_FLOAT(x);
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
    TORCH_CHECK(kernel_size > 0, "kernel_size must be > 0");

